import re
import unicodedata

def slugify(title, max_length=50):
    # Normalize accented characters to their base form and remove combining marks
    normalized = unicodedata.normalize('NFKD', title)
    ascii_only = ''.join(c for c in normalized if not unicodedata.combining(c))
    # Lowercase and replace any run of non-alphanumeric characters with a single hyphen
    slug = re.sub(r'[^a-z0-9]+', '-', ascii_only.lower()).strip('-')

    if not slug:
        return 'untitled'

    if len(slug) <= max_length:
        return slug

    words = slug.split('-')
    result = ''
    for i, word in enumerate(words):
        if i == 0:
            candidate = word
        else:
            candidate = result + '-' + word
        if len(candidate) <= max_length:
            result = candidate
        else:
            if i == 0:
                # Even the first word is too long, cut it
                result = word[:max_length]
            break
    return result
