def flatten(obj, depth=None):
    """
    Flatten nested lists and tuples into a single flat list.

    Strings, bytes, dictionaries and sets are kept as single items.
    The `depth` argument controls how many levels of nesting are flattened:
      - depth=None (default): unlimited flattening
      - depth=0: return a shallow copy of the top-level list/tuple
    If `obj` is not a list or tuple, it is wrapped in a list.
    """
    if not isinstance(obj, (list, tuple)):
        return [obj]

    result = []

    def _flatten(item, d):
        if isinstance(item, (list, tuple)):
            if d is None or d > 0:
                new_d = d - 1 if d is not None else None
                for sub in item:
                    _flatten(sub, new_d)
            else:
                # d is 0 or negative → do not flatten further
                result.append(item)
        else:
            result.append(item)

    for item in obj:
        _flatten(item, depth)

    return result
