def format_table(rows):
    """
    Format a list of rows (each a list of values) into a plain-text table.
    """
    if not rows:
        return ""

    # Determine number of columns (handle ragged rows by padding with "")
    max_cols = max(len(row) for row in rows)
    # Pad shorter rows with empty strings
    padded_rows = [row + [""] * (max_cols - len(row)) for row in rows]

    # Compute column widths based on the string representation of all cells
    widths = []
    for col in range(max_cols):
        max_width = 0
        for row in padded_rows:
            s = str(row[col])
            if len(s) > max_width:
                max_width = len(s)
        widths.append(max_width)

    def is_number(value):
        return isinstance(value, (int, float)) and not isinstance(value, bool)

    def format_cell(value, width):
        s = str(value)
        if is_number(value):
            return s.rjust(width)
        else:
            return s.ljust(width)

    # Build each row line
    lines = []
    for idx, row in enumerate(padded_rows):
        formatted_cells = [
            format_cell(cell, widths[col]) for col, cell in enumerate(row)
        ]
        lines.append(" | ".join(formatted_cells))

    # Header line is the first line; separator line is '-' repeated to the line length
    header_len = len(lines[0])
    separator = "-" * header_len

    # Combine: header, separator, then remaining rows (if any)
    output_lines = [lines[0], separator] + lines[1:]
    return "\n".join(output_lines)
