import re
from datetime import date

def parse_date(s: str) -> date:
    """
    Parse a date from text and return a datetime.date object.

    Accepted formats:
      - ISO:        YYYY-MM-DD   (e.g., 2024-03-05)
      - Day-first:  DD/MM/YYYY or DD/MM/YY (e.g., 05/03/2024 or 5/3/24)
        Day and month may be one or two digits.
        Two-digit years: 00–69 → 2000–2069, 70–99 → 1970–1999.

    Leading/trailing whitespace is ignored.
    Any other format, or an impossible date (e.g., 31/02/2024), raises ValueError.
    """
    s = s.strip()
    if not s:
        raise ValueError("empty date string")

    # ISO format: YYYY-MM-DD
    iso_match = re.fullmatch(r'(\d{4})-(\d{1,2})-(\d{1,2})', s)
    if iso_match:
        year, month, day = map(int, iso_match.groups())
        try:
            return date(year, month, day)
        except ValueError:
            raise ValueError(f"Invalid date: {s!r}")

    # Slash day-first: DD/MM/YYYY or DD/MM/YY
    slash_match = re.fullmatch(r'(\d{1,2})/(\d{1,2})/(\d{2,4})', s)
    if slash_match:
        day_str, month_str, year_str = slash_match.groups()
        day, month = int(day_str), int(month_str)
        year = int(year_str)
        if len(year_str) == 2:
            if year <= 69:
                year += 2000
            else:
                year += 1900
        try:
            return date(year, month, day)
        except ValueError:
            raise ValueError(f"Invalid date: {s!r}")

    raise ValueError(f"Unable to parse date from: '{s}'")
