def wrap(text, width):
    """
    Wrap text into lines no longer than width characters.

    Lines are broken only at spaces; a word longer than width is placed
    on a line by itself. Existing newlines are preserved as hard breaks,
    runs of spaces collapse to a single space, and no line starts or ends
    with a space. Raises ValueError if width is less than 1.
    """
    if width < 1:
        raise ValueError("width must be at least 1")

    lines = []
    for segment in text.split('\n'):
        # An empty (or whitespace‑only) segment becomes an empty line.
        if not segment.strip():
            lines.append('')
            continue

        words = segment.split()          # collapses spaces, drops leading/trailing
        current_line = []                # words of the line currently being built

        for word in words:
            if not current_line:
                # Starting a new line.
                if len(word) > width:
                    lines.append(word)   # word too long – its own line
                else:
                    current_line.append(word)
            else:
                current_line_str = ' '.join(current_line)
                if len(current_line_str) + 1 + len(word) <= width:
                    current_line.append(word)
                else:
                    # Current line is full – flush it.
                    lines.append(current_line_str)
                    if len(word) > width:
                        lines.append(word)
                        current_line = []
                    else:
                        current_line = [word]

        if current_line:
            lines.append(' '.join(current_line))

    return lines
