def parse_query(qs):
    """
    Parse a URL query string into a dict.

    - Leading '?' is ignored.
    - Keys and values are percent-decoded; '+' means a space.
    - A repeated key yields a list of all its values in order.
    - A single occurrence yields a plain string.
    - A piece without '=' yields a key with an empty string value.
    - Empty pieces are skipped.
